<!doctype html>
<html lang="pl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="theme-color" content="#0f172a"><link rel="manifest" href="/trainingapp/public/manifest.json"><script src="https://cdn.tailwindcss.com"></script><script src="https://cdn.jsdelivr.net/npm/chart.js"></script><link rel="stylesheet" href="/trainingapp/public/css/app.css"><title>FitTrack — Progres</title></head>
<body class="bg-slate-50 text-slate-900"><main class="mx-auto max-w-3xl px-4 pb-28 pt-6 space-y-6"><header><a class="text-sm font-bold text-slate-500" href="/trainingapp/">← FitTrack</a><h1 class="mt-2 text-3xl font-black">Progres</h1><p class="mt-1 text-slate-500">Codzienna masa ciała i cotygodniowe obwody.</p></header>
<section class="grid grid-cols-2 gap-3"><div class="rounded-2xl bg-white p-4 ring-1 ring-slate-200"><p class="text-sm text-slate-500">Ostatnia masa</p><p id="latestWeight" class="mt-1 text-2xl font-black">—</p><p id="lastWeighDate" class="mt-1 text-xs text-slate-400">Brak pomiaru</p></div><div class="rounded-2xl bg-white p-4 ring-1 ring-slate-200"><p class="text-sm text-slate-500">Zmiana od pierwszego pomiaru</p><p id="weightChange" class="mt-1 text-2xl font-black">—</p></div></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><div><h2 class="text-xl font-bold">Masa ciała w czasie</h2><p class="text-sm text-slate-500">Trend masy ciała.</p></div><div class="relative h-64"><canvas id="weightChart"></canvas></div></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><div><h2 class="text-xl font-bold">Kalorie i makroskładniki</h2><p class="text-sm text-slate-500">Dzienne wpisy z ostatnich 30 dni.</p></div><div class="relative h-64"><canvas id="calorieChart"></canvas></div><div class="relative h-64"><canvas id="macroChart"></canvas></div></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-4"><div><h2 class="text-xl font-bold">Pomiar ciała</h2><p class="text-sm text-slate-500">Masa ciała jest zapisywana codziennie. Obwody są dostępne wyłącznie w piątki.</p></div><div id="weeklyStatus" class="rounded-xl bg-slate-50 p-3 text-sm text-slate-600">Sprawdzam dzisiejszy wpis…</div><form id="form" class="grid grid-cols-2 gap-3"><label class="col-span-2 text-sm font-semibold">Data pomiaru<input id="measurementDate" name="measurement_date" type="date" readonly required class="mt-1 w-full rounded-xl border bg-slate-100 p-3"></label><label class="col-span-2 text-sm font-semibold">Masa ciała (kg)<input name="weight_kg" type="number" min="20" max="400" step="0.1" required class="mt-1 w-full rounded-xl border p-3" placeholder="np. 96,4"></label><div id="circumferenceNotice" class="col-span-2 rounded-xl bg-blue-50 p-3 text-sm text-blue-800">Obwody są zablokowane poza piątkiem.</div><div id="circumferenceFields" class="col-span-2 grid grid-cols-2 gap-3"><label class="text-sm font-semibold">Talia (cm)<input name="waist_cm" type="number" min="1" max="300" step="0.1" class="mt-1 w-full rounded-xl border p-3"></label><label class="text-sm font-semibold">Klatka (cm)<input name="chest_cm" type="number" min="1" max="300" step="0.1" class="mt-1 w-full rounded-xl border p-3"></label><label class="text-sm font-semibold">Ramię (cm)<input name="arm_cm" type="number" min="1" max="150" step="0.1" class="mt-1 w-full rounded-xl border p-3"></label><label class="text-sm font-semibold">Udo (cm)<input name="thigh_cm" type="number" min="1" max="200" step="0.1" class="mt-1 w-full rounded-xl border p-3"></label></div><button id="saveButton" class="col-span-2 rounded-xl bg-slate-900 p-3 font-bold text-white">Zapisz dzisiejszą masę</button><button id="cancelEdit" type="button" class="col-span-2 hidden rounded-xl border p-3 font-bold">Wróć do dzisiejszego wpisu</button><p id="notice" class="col-span-2 text-sm"></p></form></section>
<section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><h2 class="text-xl font-bold">Historia pomiarów</h2><div id="history" class="space-y-3">Ładowanie…</div></section><section class="rounded-3xl bg-white p-5 shadow-sm ring-1 ring-slate-200 space-y-3"><h2 class="text-xl font-bold">Historia treningów</h2><div id="sessions" class="space-y-3">Ładowanie…</div></section></main>
<nav class="fixed inset-x-0 bottom-0 z-40 border-t bg-white/95 backdrop-blur"><div class="mx-auto grid max-w-3xl grid-cols-5 text-center text-xs font-bold"><a class="p-3" href="/trainingapp/">⌂<br>Home</a><a class="p-3 text-slate-500" href="/trainingapp/calendar.php">▦<br>Kalendarz</a><a class="p-3 text-slate-500" href="/trainingapp/workouts.php">◈<br>Treningi</a><a class="p-3" href="/trainingapp/progress.php">↗<br>Progres</a><a class="p-3 text-slate-500" href="/trainingapp/nutrition.php">◉<br>Dieta</a></div></nav>
<script>
const API='/trainingapp/api';const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));async function api(p,o={}){const r=await fetch(API+'/'+p,{headers:{'Content-Type':'application/json'},...o});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'Błąd API');return d}const pad=n=>String(n).padStart(2,'0');function localDate(d=new Date()){return d.getFullYear()+'-'+pad(d.getMonth()+1)+'-'+pad(d.getDate())}const today=localDate();let measurements=[],weightChart=null,calorieChart=null,macroChart=null,editingDate=today;
function isFriday(date){return new Date(date+'T12:00:00').getDay()===5}
function setFormRecord(date,record=null){editingDate=date;const form=document.querySelector('#form');form.reset();document.querySelector('#measurementDate').value=date;document.querySelector('[name=weight_kg]').value=record?.weight_kg??'';for(const k of ['waist_cm','chest_cm','arm_cm','thigh_cm'])form.elements[k].value=record?.[k]??'';const canMeasure=isFriday(date);document.querySelector('#circumferenceFields').classList.toggle('hidden',!canMeasure);document.querySelector('#circumferenceNotice').classList.toggle('hidden',canMeasure);document.querySelector('#circumferenceNotice').textContent=canMeasure?'':'Obwody są zablokowane poza piątkiem.';document.querySelectorAll('#circumferenceFields input').forEach(el=>{el.disabled=!canMeasure;el.required=false});const isToday=date===today;document.querySelector('#saveButton').textContent=record?(isToday?'Zapisz zmiany dzisiejszego wpisu':'Zapisz zmiany pomiaru'): 'Zapisz dzisiejszą masę';document.querySelector('#cancelEdit').classList.toggle('hidden',isToday);document.querySelector('#notice').textContent='';document.querySelector('#weeklyStatus').textContent=record?(isToday?'Dzisiejszy wpis już istnieje. Możesz edytować zapisane wartości.':'Edytujesz istniejący wpis z '+date+'.'):(canMeasure?'Nie ma jeszcze wpisu na dziś. Możesz zapisać masę i obwody.':'Nie ma jeszcze wpisu na dziś. Zapisz masę ciała.');document.querySelector('#weeklyStatus').className='rounded-xl p-3 text-sm '+(record?'bg-emerald-50 text-emerald-800':'bg-slate-50 text-slate-600')}
function chartOptions(yTitle){return {responsive:true,maintainAspectRatio:false,interaction:{mode:'index',intersect:false},plugins:{legend:{position:'bottom'}},scales:{x:{ticks:{maxTicksLimit:8}},y:{beginAtZero:false,title:{display:true,text:yTitle}}}}}
async function load(){const [allMeasurements,sessions,nutrition]=await Promise.all([api('measurements'),api('workout-sessions?limit=30'),api('nutrition?from='+localDate(new Date(Date.now()-29*86400000))+'&to='+today)]);measurements=allMeasurements;const todayRecord=measurements.find(x=>x.measurement_date===today);setFormRecord(today,todayRecord||null);const fridayRecord=measurements.find(x=>isFriday(x.measurement_date)&&['waist_cm','chest_cm','arm_cm','thigh_cm'].some(k=>x[k]!==null&&x[k]!==''));if(fridayRecord&&isFriday(today)&&todayRecord)document.querySelector('#weeklyStatus').textContent='Dzisiejszy wpis został już zapisany. Możesz edytować istniejące wartości.';const weights=measurements.filter(x=>x.weight_kg!==null&&x.weight_kg!=='').slice().sort((a,b)=>a.measurement_date.localeCompare(b.measurement_date));document.querySelector('#latestWeight').textContent=weights.length?Number(weights[weights.length-1].weight_kg).toFixed(1)+' kg':'—';document.querySelector('#lastWeighDate').textContent=weights.length?'Ostatni wpis: '+weights[weights.length-1].measurement_date:'Brak wpisów';if(weights.length>1){const delta=Number(weights[weights.length-1].weight_kg)-Number(weights[0].weight_kg);document.querySelector('#weightChange').textContent=(delta>0?'+':'')+delta.toFixed(1)+' kg';document.querySelector('#weightChange').className='mt-1 text-2xl font-black '+(delta<0?'text-emerald-700':delta>0?'text-rose-600':'')}else document.querySelector('#weightChange').textContent='—';
if(weightChart)weightChart.destroy();weightChart=new Chart(document.getElementById('weightChart'),{type:'line',data:{labels:weights.map(x=>x.measurement_date),datasets:[{label:'Masa (kg)',data:weights.map(x=>Number(x.weight_kg)),tension:.25,spanGaps:true}]},options:chartOptions('kg')});
const food=nutrition.slice().sort((a,b)=>a.entry_date.localeCompare(b.entry_date));if(calorieChart)calorieChart.destroy();calorieChart=new Chart(document.getElementById('calorieChart'),{type:'line',data:{labels:food.map(x=>x.entry_date),datasets:[{label:'Spożyte kcal',data:food.map(x=>Number(x.calories)||0),tension:.25},{label:'Spalone kcal',data:food.map(x=>x.burned_calories===null?null:Number(x.burned_calories)),tension:.25}]},options:chartOptions('kcal')});if(macroChart)macroChart.destroy();macroChart=new Chart(document.getElementById('macroChart'),{type:'line',data:{labels:food.map(x=>x.entry_date),datasets:[{label:'Białko (g)',data:food.map(x=>Number(x.protein_g)||0),tension:.25},{label:'Węglowodany (g)',data:food.map(x=>Number(x.carbs_g)||0),tension:.25},{label:'Tłuszcze (g)',data:food.map(x=>Number(x.fats_g)||0),tension:.25}]},options:chartOptions('g')});
document.querySelector('#history').innerHTML=measurements.map(x=>'<article class="rounded-2xl border p-4"><div class="flex items-start justify-between gap-3"><div><h3 class="font-bold">'+esc(x.measurement_date)+'</h3><p class="mt-1 text-lg font-black">'+(x.weight_kg!==null?esc(x.weight_kg)+' kg':'Brak masy')+'</p><p class="text-sm text-slate-500">Talia '+(x.waist_cm??'—')+' cm · Klatka '+(x.chest_cm??'—')+' cm · Ramię '+(x.arm_cm??'—')+' cm · Udo '+(x.thigh_cm??'—')+' cm</p></div><button class="edit shrink-0 rounded-lg border px-3 py-2 text-sm" data-date="'+esc(x.measurement_date)+'">Edytuj</button></div></article>').join('')||'<p class="text-slate-500">Brak zapisanych pomiarów.</p>';document.querySelectorAll('.edit').forEach(b=>b.onclick=()=>{const x=measurements.find(x=>x.measurement_date===b.dataset.date);setFormRecord(x.measurement_date,x);window.scrollTo({top:0,behavior:'smooth'})});
document.querySelector('#sessions').innerHTML=sessions.map(x=>'<article class="rounded-2xl border p-4"><h3 class="font-bold">'+esc(x.workout_name_snapshot)+'</h3><p class="text-sm text-slate-500">'+esc(x.started_at)+' · '+(x.ended_at?'Zakończony':'W trakcie')+'</p><p class="mt-1 text-sm">'+(x.exercise_count||0)+' ćwiczeń · '+(x.set_count||0)+' serii'+(x.duration_seconds?' · '+Math.round(x.duration_seconds/60)+' min':'')+'</p><a class="mt-2 inline-flex rounded-lg border px-3 py-2 text-sm" href="/trainingapp/workout.php?session_id='+x.id+'">'+(x.ended_at?'Podgląd':'Wróć do treningu')+'</a></article>').join('')||'<p class="text-slate-500">Historia treningów pojawi się tutaj po pierwszej sesji.</p>'}
function showError(e){const n=document.querySelector('#notice');n.textContent=e.message;n.className='col-span-2 text-sm text-red-600'}
document.querySelector('#form').onsubmit=async e=>{e.preventDefault();const body=Object.fromEntries(new FormData(e.target).entries());body.measurement_date=editingDate;for(const k of ['weight_kg','waist_cm','chest_cm','arm_cm','thigh_cm'])body[k]=body[k]===''?null:Number(body[k]);const existing=measurements.find(x=>x.measurement_date===editingDate);if(!existing&&editingDate!==today){showError(new Error('Możesz dodać tylko dzisiejszy wpis. Starsze wpisy można wyłącznie edytować.'));return}if(!isFriday(editingDate)){for(const k of ['waist_cm','chest_cm','arm_cm','thigh_cm'])body[k]=existing?.[k]??null}try{await api('measurements',{method:'POST',body:JSON.stringify(body)});await load();setFormRecord(editingDate,measurements.find(x=>x.measurement_date===editingDate)||null);document.querySelector('#notice').textContent='Zapisano. Wpis z tej daty można teraz tylko edytować.';document.querySelector('#notice').className='col-span-2 text-sm text-emerald-700'}catch(err){showError(err)}};
document.querySelector('#cancelEdit').onclick=()=>{setFormRecord(today,measurements.find(x=>x.measurement_date===today)||null);window.scrollTo({top:0,behavior:'smooth'})};load().catch(showError);
</script></body></html>